      "content": "var __rewriteRelativeImportExtension = (this && this.__rewriteRelativeImportExtension) || function (path, preserveJsx) {\n    if (typeof path === \"string\" && /^\\.\\.?\\//.test(path)) {\n        return path.replace(/\\.(tsx)$|((?:\\.d)?)((?:\\.[^./]+?)?)\\.([cm]?)ts$/i, function (m, tsx, d, ext, cm) {\n            return tsx ? preserveJsx ? \".jsx\" : \".js\" : d && (!ext || !cm) ? m : (d + ext + \".\" + cm.toLowerCase() + \"js\");\n        });\n    }\n    return path;\n};\nimport { randomUUID } from 'node:crypto';\nimport { readFile } from 'node:fs/promises';\nimport path from 'node:path';\nimport { Comparer, ChoiceChangedError, publicView, RunStore, RecordUnavailableError, defaultHome, createExampleRepo, exampleTask, DEFAULT_GENERATION_MS, CANDIDATE_LABELS, PICK_REASONS, } from '../core/index.js';\nimport { identitiesShown } from '../core/run-view.js';\nimport { EMPTY_TRACE, traceView } from '../core/trace.js';\nimport { traceOf } from './trace.js';\nimport { commandResultText, parseAbInput } from './conversation.js';\nimport { profileProject } from '../core/project.js';\nimport { checkEnableGit, enableGit, resolveWorkspace } from '../core/workspace.js';\nimport { comparisonPlan, contextRequestOf, defaultPreferences, parsePreferences, parseUiSubmission, PreferencesStore } from './preferences.js';\nimport { buildConversationContext, CONTEXT_CHARS, listedEntries, MESSAGE_CHARS } from './conversation-context.js';\nimport { StepMemory, withComparisonNotes } from './step-memory.js';\nimport { historyPage, HistoryQueryError } from './history.js';\nimport { observedRoute, selectedRoute } from './routes.js';\nimport { createProjectProcess, projectCommandArgv } from './project-process.js';\nimport { conversationResolver, SessionAccessError } from './session.js';\nimport { readComparisonStatus } from './status.js';\nimport { withCurrentComparisonState } from './current-state.js';\nimport { assertComparisonActionRoutes, dispatchComparisonAction } from './