rue && task.trim() === '' ? exampleTask(exampleKind) : task,\n                ...plan,\n                hostContext: agent,\n                sessionId: agent.session.id,\n                ...(follows === undefined ? {} : { follows }),\n                origin: { kind: 'panel' },\n                windowsProcessCompat,\n                ...(minutes === undefined ? {} : { generationMs: minutes * 60_000 }),\n            });\n            return present(r);\n        },\n        async reopenPreview(b) {\n            const l = label(b.label);\n            if (l === undefined)\n                throw new HttpError(400, 'label must be A, B, C or D');\n            return present(await comparer.reopenPreview(runIdOf(b), l));\n        },\n        async salvage(b) {\n            const l = label(b.label);\n            if (l === undefined)\n                throw new HttpError(400, 'label must be A, B, C or D');\n            return present(await comparer.salvage(runIdOf(b), l));\n        },\n        async retryVerification(b) {\n            const l = label(b.label);\n            if (l === undefined)\n                throw new HttpError(400, 'label must be A, B, C or D');\n            return present(await comparer.retryVerification(runIdOf(b), l));\n        },\n        async choose(b) {\n            const pick = b.pick === 'none' ? 'none' : label(b.pick);\n            if (pick === undefined)\n                throw new HttpError(400, 'pick must be a candidate label or none');\n            return present(await comparer.choose(runIdOf(b), pick, typeof b.note === 'string' ? b.note.slice(0, 500) : undefined));\n        },\n        /** Why the pick won: known reasons and a short note. The next step of the conversation hears it. */\n        async explain(b) {\n            if (!CANDIDATE_LABELS.includes(b.pick))\n                throw new HttpError(400, 'pick must name the version being explained');\n            const reasons = Array.isArray(b.reasons) ? b.reasons : [];\n            if (reasons.length > PICK_REASONS.length || reasons.some(reason => !PICK_REASONS.includes(reason)))\n                throw new HttpError(400, 'reasons must be known pick reasons');\n            if (b.note !== undefined && typeof b.note !== 'string')\n                throw new HttpError(400, 'note must be text');\n            return present(await comparer.explainChoice(runIdOf(b), reasons, typeof b.note === 'string' ? b.note : undefined, b.pick));\n        },\n        async preflight(b) { return { ...await comparer.adoptPreflight(runIdOf(b)), protectedWorktreeApply: true }; },\n        async adopt(b) { return present(await comparer.adopt(runIdOf(b), b.mode === 'branch' ? 'branch' : b.mode === 'folder' ? 'folder' : 'worktree')); },\n        /**\n         * Turn the conversation's folder into a Git repository so both versions\n         * start from its files. `check: true` only reports whether it may.\n         */\n        async enableGit(b, signal) {\n            const agent = await agentFor(b, signal);\n            const cwd = agent.session.header.cwd;\n            if (!cwd)\n                throw new HttpError(400, '这条对话没有目录');\n            if (b.check === true)\n                return checkEnableGit(cwd);\n            try {\n                await enableGit(cwd);\n            }\n            catch (error) {\n                throw new HttpError(409, error.message);\n            }\n            return describeProject(cwd);\n        },\n        /** One file a version wrote. Before the reveal only results judged by their files can be read. */\n        async candidateFile(b) {\n            const r = await comparer.get(runIdOf(b));\n            const c = r?.candidates.find((x) => x.label === label(b.label));\n            if (r === undefined || c === undefined)\n                throw new HttpError(404, '没有这个候选');\n            if (!identitiesShown(r) && c.result !== 'files')\n                throw new HttpError(403, '选择之后才能查看改动');\n            if (typeof b.path !== 'string' || !(c.touchedFiles ?? []).includes(b.path))\n                throw new HttpError(404, '这一版没有写这个文件');\n            return comparer.readResultFile(r.runId, c.label, b.path);\n        },\n        async cancelAdoption(b, signal) {\n            const runId = runIdOf(b), record = await comparer.get(runId);\n            if (!record)\n                throw new HttpError(404, '没有这次比较');\n            return present(await comparer.cancelAdoption(runId));\n        },\n        async revert(b) { return present(await comparer.revert(runIdOf(b))); },\n        async recover(b) { return present(await comparer.recoverAdoption(runIdOf(b), b.action === 'keep' ? 'keep' : 'restore')); },\n        async cancel(b) { const r = await comparer.cancel(runIdOf(b), label(b.label)); return r === undefined ? null : present(r); },\n        async cleanup(b, signal) { return api.releaseCopies(b, signal); },\n        async copyCleanupPlan(b, signal) {\n            const agent = await agentFor(b, signal);\n            const runId = runIdOf(b), record = await comparer.get(runId);\n            if (!record)\n                throw new HttpError(404, '没有这次比较');\n            return { ...await comparer.copyCleanupPlan(runId, signal), otherSession: !record.sessionId || record.sessionId !== agent.session.id };\n        },\n        async releaseCopies(b, signal) {\n            const agent = await agentFor(b, signal);\n            const runId = runIdOf(b), record = await comparer.get(runId);\n            if (!record)\n                throw new HttpError(404, '没有这次比较');\n            if (record.sessionId && record.sessionId !== agent.session.id && b.confirmOtherSession !== true)\n                throw new HttpError(409, '这次比较属于另一个对话，请明确确认后再释放副本。');\n            if (typeof b.token !== 'string')\n                throw new HttpError(400, '请先查看本次副本清单');\n            return present(await comparer.releaseCopies(runId, b.token));\n        },\n        async shot(b) {\n            const r = await comparer.get(runIdOf(b));\n            const c = r?.candidates.find((x) => x.label === label(b.label));\n            const file = b.mobile === true ? c?.mobileScreenshot : c?.screenshot;\n            if (file === undefined)\n                throw new HttpError(404, 'no screenshot');\n            return { dataUrl: `data:image/png;base64,${(await readFile(file)).toString('base64')}` };\n        },\n        /**\n         * What a version did while it worked: thinking, tool calls and their\n         * output. Before a blind pick, words that name its style are masked.\n         * `summary: true` returns the counts and only the newest step, which says\n         * what the version is doing while its steps are closed.\n         */\n        async trace(b) {\n            const runId = runIdOf(b), r = await comparer.get(runId);\n            const c = r?.candidates.find((x) => x.label === label(b.label));\n            if (r === undefined || c === undefined)\n                throw new HttpError(404, '没有这个候选');\n            const stored = await comparer.readTrace(runId, c.label) ?? EMPTY_TRACE;\n            return traceView(stored, { blind: !identitiesShown(r), ...(c.strategy ? { strategy: c.strategy } : {}), summary: b.summary === true });\n        },\n        async patch(b) {\n            const r = await comparer.get(runIdOf(b));\n            const c = r?.candidates.find((x) => x.label === label(b.label));\n            if (r === undefined || c?.patchFile === undefined)\n                throw new HttpError(404, 'no patch');\n            // An open comparison shows every change from the start; a blind one after the pick.\n            if (!identitiesShown(r))\n                throw new HttpError(403, '选择之后才能查看改动');\n            const text = await readFile(c.patchFile, 'utf8');\n            return { sha256: c.patchSha256, truncated: text.length > 400_000, text: text.slice(0, 400_000) };\n        },\n    };\n    assertComparisonActionRoutes(api);\n    ctx.inject(['webServer', 'connection'], (web) => web.effect(() => web.webServer.register({\n        kind: 'prefix',\n        path: ROUTE,\n        handler: async (req, res) => {\n            if (web.connection.requestRejection(req) !== undefined)\n                return json(res, 403, { ok: false, error: 'forbidden' });\n            if (req.method !== 'POST')\n                return json(res, 405, { ok: false, error: 'method not allowed' });\n            const method = new URL(req.url ?? '/', 'http://dsh.internal').pathname.slice(ROUTE.length + 1);\n            const handler = Object.hasOwn(api, method) ? api[method] : undefined;\n            if (handler === undefined)\n                return json(res, 404, { ok: false, error: `unknown method ${method}` });\n            const ctl = new AbortController();\n            res.once('close', () => { if (!res.writableEnded)\n                ctl.abort(); });\n            try {\n                const body = await readBody(req);\n                const value = await dispatchComparisonAction({ method, comparer, caller: () => agentFor(body, ctl.signal), runId: () => runIdOf(body), confirmation: body.confirmOtherSession, signal: ctl.signal }, () => handler(body, ctl.signal));\n                json(res, 200, { ok: true, value });\n            }\n            catch (error) {\n                const status = error instanceof HttpError || error instanceof SessionAccessError ? error.status : error instanceof HistoryQueryError ? 400 : error instanceof RecordUnavailableError || error instanceof ChoiceChangedError || error.name === 'BusyError' ? 409 : 500;\n                json(res, status, { ok: false, error: error.message, ...(error instanceof HttpError && error.code ? { code: error.code } : {}) });\n            }\n        },\n    }), 'agent-compare: /agent-compare/api routes'));\n}\n/** Whether `child` is `parent` or below it, compared the way the platform compares paths. */\nexport function insideDirectory(parent, child) {\n    if (!child)\n        return false;\n    const fold = (value) => process.platform === 'win32' ? path.resolve(value).toLowerCase() : path.resolve(value);\n    const relative = path.relative(fold(parent), fold(child));\n    return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative));\n}\nfunction json(res, status, body) {\n    if (res.headersSent)\n        return;\n    res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });\n    res.end(JSON.stringify(body));\n}\n"
    },
    {
      "path": "lib/core/trace.js",
      "content": "/**\n * What a version did while it worked: its thinking, its tool calls with their\n * input and output, and any words it wrote between steps. Built by the host\n * from the version's own session; the final reply is kept apart from it.\n *\n * A trace is bounded: long texts are cut and a very long session keeps its\n * opening and its latest steps. It is stored next to the run's other\n * artifacts, not in the run record.\n */\nimport { mkdir, readFile, rename, writeFile } from 'node:fs/promises';\nimport path from 'node:path';\nexport const TRACE_LIMITS = { items: 320, head: 40, thinking: 6000, text: 4000, input: 1500, output: 2000, target: 140 };\nexport function clip(text, max) {\n    return text.length <= max ? { text, cut: false } : { text: `${text.slice(0, max)}…`, cut: true };\n}\n/** Keep the opening and the latest items of a long session. */\nexport function boundItems(items) {\n    if (items.length <= TRACE_LIMITS.items)\n        return { items, cut: false, omitted: 0 };\n    const tail = TRACE_LIMITS.items - TRACE_LIMITS.head;\n    return { items: [...items.slice(0, TRACE_LIMITS.head), ...items.slice(-tail)], cut: true, omitted: items.length - TRACE_LIMITS.items };\n}\nexport const EMPTY_TRACE = { items: [], steps: 0, tools: 0, thinking: 0, truncated: false, done: false, updatedAt: 0 };\nconst STYLE_WORDS = ['CONSERVATIVE', 'BOLD', 'MINIMAL', 'POLISHED', 'VIBRANT', 'FRIENDLY', 'RIGOROUS', 'LEAN', 'BALANCED', 'CUSTOM'];\nconst STYLE_NAMES = [['稳妥', 'Conservative'], ['大胆', 'Bold'], ['极简', 'Minimal'], ['精致', 'Polished'], ['活力', 'Vibrant'], ['易用', 'Friendly'], ['严谨', 'Rigorous'], ['轻快', 'Lean'], ['均衡', 'Balanced']];\nconst ZH = STYLE_NAMES.map(([zh]) => zh).join('|'), EN = STYLE_NAMES.map(([, en]) => en).join('|');\n/** Shown in place of a style name while a blind comparison is still blind. */\nexport const MASK = '▒▒';\nconst escape = (s) => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n/**\n * Mask what would name a version's style before a blind pick: the style\n * words of the instructions, a style name used as a style (\"极简风格\",\n * \"Bold style\", \"稳妥 · Conservative\") and a custom description. Ordinary use\n * of the same words (\"font-weight: bold\", \"一个极简的页面\") stays readable.\n */\nexport function maskStyle(text, strategy) {\n    let out = text.replace(new RegExp(`\\\\b(?:Strategy|Style)\\\\s*:\\\\s*(?:${STYLE_WORDS.join('|')})\\\\b`, 'g'), MASK)\n        .replace(new RegExp(`\\\\b(?:${STYLE_WORDS.join('|')})\\\\b`, 'g'), MASK);\n    for (const [zh, en] of STYLE_NAMES)\n        out = out.replace(new RegExp(`${zh}\\\\s*·\\\\s*${en}`, 'gi'), MASK);\n    // A style name the text uses to describe its own approach: \"Bold style\", \"went bold\",\n    // \"a minimal take\", \"极简风格\", \"走稳妥路线\", \"偏大胆\".\n    out = out.replace(new RegExp(`(?:${ZH})(?=\\\\s*(?:风格|策略|路线|方向|版本|取向|路子|思路))`, 'g'), MASK)\n        .replace(new RegExp(`((?:走|偏|偏向|主打|采用|选了|按照|按)\\\\s*)(?:${ZH})`, 'g'), `$1${MASK}`)\n        .replace(new RegExp(`\\\\b(?:${EN})(?=\\\\s+(?:style|strategy|approach|direction|take|route|version|vibe)\\\\b)`, 'gi'), MASK)\n        .replace(new RegExp(`\\\\b((?:went|go|going|gone|kept it|keep it|keeping it|stayed|played it|leaned|leaning)\\\\s+)(?:${EN})\\\\b`, 'gi'), `$1${MASK}`);\n    const note = strategy?.id === 'custom' ? strategy.title.replace(/^自定义 · /, '').replace(/…$/, '').trim() : '';\n    if (note.length >= 4)\n        out = out.replace(new RegExp(escape(note), 'g'), MASK);\n    return out;\n}\nexport function maskTrace(trace, strategy) {\n    const mask = (value) => value === undefined ? undefined : maskStyle(value, strategy);\n    return {\n        ...trace,\n        items: trace.items.map(item => ({\n            ...item,\n            ...(item.text === undefined ? {} : { text: mask(item.text) }),\n            ...(item.target === undefined ? {} : { target: mask(item.target) }),\n            ...(item.input === undefined ? {} : { input: mask(item.input) }),\n            ...(item.output === undefined ? {} : { output: mask(item.output) }),\n        })),\n    };\n}\n/**\n * What a reader is shown of a stored trace. Before a blind pick, words that\n * name the version's style are masked. A summary keeps the counts and the\n * newest few steps, enough to show live what the version is doing.\n */\nexport const SUMMARY_ITEMS = 3;\nexport function traceView(stored, options) {\n    const wanted = options.summary === true ? { ...stored, items: stored.items.slice(-SUMMARY_ITEMS) } : stored;\n    return { ...(options.blind ? maskTrace(wanted, options.strategy) : wanted), masked: options.blind };\n}\nexport function traceFile(artifacts, label) {\n    return path.join(artifacts, `${label}.trace.json`);\n}\n/** Replace the stored trace in one step, so a reader never sees half a file. */\nexport async function writeTrace(file, trace) {\n    await mkdir(path.dirname(file), { recursive: true });\n    const temporary = `${file}.${process.pid}.${Date.now()}.tmp`;\n    await writeFile(temporary, JSON.stringify(trace));\n    await rename(temporary, file);\n}\nexport async function readTrace(file) {\n    try {\n        const value = JSON.parse(await readFile(file, 'utf8'));\n        return value && Array.isArray(value.items) ? value : undefined;\n    }\n    catch {\n        return undefined;\n    }\n}\n"
    },
    {
      "path": "lib/core/deps-warm.js",
      "content": "/**\n * Install dependencies once, while the versions are still being generated.\n *\n * Most versions do not change a project's dependencies. For an npm project\n * with a lockfile, the baseline's manifest is installed with the same frozen\n * command into a private directory of the run as soon as the copies exist.\n * A version whose manifest files are byte-identical to that baseline gets\n * its own copy of that tree instead of running its own install.\n * Anything unusual (another package manager, local `file:` packages, root\n * install scripts, a changed manifest, a failed or unfinished warm install,\n * a copy error) falls back to the version's own frozen install.\n *\n * The warm tree is outside every version's copy and each version gets its own\n * files, so no version can change the warm tree or another version.\n */\nimport { createHash } from 'node:crypto';\nimport { constants, existsSync } from 'node:fs';\nimport { copyFile, lstat, mkdir, opendir, readFile, readdir, realpath, rm, stat, symlink } from 'node:fs/promises';\nimport path from 'node:path';\n/** Files that decide what `npm ci` installs. */\nexport const NPM_MANIFESTS = ['package.json', 'package-lock.json', 'npm-shrinkwrap.json', '.npmrc'];\nconst ROOT_SCRIPTS = ['preinstall', 'install', 'postinstall', 'prepare', 'prepublish'];\nconst digest = (bytes) => createHash('sha256').update(bytes).digest('hex');\n/** Fingerprint the manifest files of a project directory; absent files are recorded as absent. */\nexport async function manifestDigests(projectDir) {\n    const out = {};\n    for (const file of NPM_MANIFESTS) {\n        const full = path.join(projectDir, file);\n        out[file] = existsSync(full) ? digest(await readFile(full)) : null;\n    }\n    return out;\n}\n/**\n * Whether this project's dependencies can be installed ahead: an npm lockfile,\n * no root install scripts (they may need project files or write into the\n * project), and no local packages linked from inside the repository.\n */\nexport async function warmable(projectDir) {\n    let pkg;\n    let lock;\n    try {\n        pkg = JSON.parse(await readFile(path.join(projectDir, 'package.json'), 'utf8'));\n        lock = JSON.parse(await readFile(path.join(projectDir, 'package-lock.json'), 'utf8'));\n    }\n    catch {\n        return { ok: false, reason: 'no npm lockfile' };\n    }\n    if (typeof pkg.packageManager === 'string' && !pkg.packageManager.startsWith('npm@'))\n        return { ok: false, reason: 'another package manager' };\n    if (existsSync(path.join(projectDir, 'pnpm-lock.yaml')) || existsSync(path.join(projectDir, 'yarn.lock')))\n        return { ok: false, reason: 'several lockfiles' };\n    if (ROOT_SCRIPTS.some(name => typeof pkg.scripts?.[name] === 'string'))\n        return { ok: false, reason: 'root install scripts' };\n    for (const entry of Object.values(lock.packages ?? {})) {\n        if (entry?.link === true || (typeof entry?.resolved === 'string' && entry.resolved.startsWith('file:')))\n            return { ok: false, reason: 'local packages' };\n    }\n    return { ok: true };\n}\n/** Copy the manifest files into the warm directory. */\nexport async function stageManifests(projectDir, warmDir) {\n    await mkdir(warmDir, { recursive: true });\n    for (const file of NPM_MANIFESTS) {\n        const from = path.join(projectDir, file);\n        if (existsSync(from))\n            await copyFile(from, path.join(warmDir, file));\n    }\n    return { manifests: await manifestDigests(warmDir) };\n}\nexport function sameManifests(a, b) {\n    return NPM_MANIFESTS.every(file => (a[file] ?? null) === (b[file] ?? null));\n}\n/** Files copied at once: enough to keep the disk busy, few enough to stay clear of open-file limits. */\nexport const COPY_CONCURRENCY = 32;\n/**\n * Recreate `from` at `to` as an independent copy, so nothing a version's\n * checks write can reach the warm tree or another version. Files are copied\n * many at a time, and cloned where the file system can share blocks until a\n * write. Internal links are relocated into the copy. Escaping or dangling\n * links, redirected roots and a nonempty destination reject the copy so\n * the caller can use the version's own frozen install instead.\n */\nexport async function copyTree(from, to) {\n    const plainDirectory = async (dir, role) => {\n        const info = await lstat(dir);\n        if (!info.isDirectory() || info.isSymbolicLink())\n            throw new Error(`${role} must be a plain directory`);\n    };\n    const inside = (root, target) => {\n        const relative = path.relative(root, target);\n        return relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);\n    };\n    await plainDirectory(from, 'Dependency source');\n    const sourceRoot = await realpath(from);\n    await mkdir(to, { recursive: true });\n    await plainDirectory(to, 'Dependency destination');\n    const targetRoot = await realpath(to);\n    if (inside(sourceRoot, targetRoot) || inside(targetRoot, sourceRoot))\n        throw new Error('Dependency source and destination must be separate directories');\n    if ((await readdir(targetRoot)).length)\n        throw new Error('Dependency destination must be empty');\n    const files = [];\n    const links = [];\n    const walk = async (src, dest) => {\n        await plainDirectory(src, 'Dependency source');\n        await mkdir(dest, { recursive: true });\n        await plainDirectory(dest, 'Dependency destination');\n        for await (const entry of await opendir(src)) {\n            const s = path.join(src, entry.name), d = path.join(dest, entry.name);\n            if (entry.isDirectory())\n                await walk(s, d);\n            else if (entry.isSymbolicLink()) {\n                const target = await realpath(s);\n                if (!inside(sourceRoot, target))\n                    throw new Error('Link resolves outside the dependency tree');\n                links.push({ dest: d, target: path.join(targetRoot, path.relative(sourceRoot, target)), directory: (await stat(s)).isDirectory() });\n            }\n            else\n                files.push([s, d]);\n        }\n    };\n    await walk(sourceRoot, targetRoot);\n    for (const link of links) {\n        const kind = link.directory ? 'junction' : 'file';\n        const target = process.platform === 'win32' && link.directory ? link.target : path.relative(path.dirname(link.dest), link.target) || '.';\n        await symlink(target, link.dest, process.platform === 'win32' ? kind : undefined);\n    }\n    let next = 0, failed = false;\n    // A rejected copy must not leave other workers writing into the caller's\n    // fallback installation. Stop queued work and drain every in-flight write.\n    const results = await Promise.allSettled(Array.from({ length: Math.min(COPY_CONCURRENCY, files.length) }, async () => {\n        while (!failed && next < files.length) {\n            const [s, d] = files[next++];\n            try {\n                await copyFile(s, d, constants.COPYFILE_FICLONE);\n            }\n            catch (error) {\n                failed = true;\n                throw error;\n            }\n        }\n    }));\n    const error = results.find(result => result.status === 'rejected');\n    if (error?.status === 'rejected')\n        throw error.reason;\n    return files.length;\n}\nexport async function removeTree(dir) {\n    await rm(dir, { recursive: true, force: true, maxRetries: 3 });\n}\n"
    },
    {
      "path": "lib/core/preview.js",
      "content": "import { createServer } from 'node:net';\nimport { createServer as createHttpServer } from 'node:http';\nimport { createReadStream, existsSync, realpathSync, statSync } from 'node:fs';\nimport { randomBytes } from 'node:crypto';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { commandHasMarkers, DiagnosticLog, killTree, spawnSpec, startLongRunning, Tail } from './proc.js';\nimport { prepareProjectProcess } from './project-process.js';\nimport { fetchPreview } from './preview-url.js';\nimport { inspectProject } from './project.js';\n/** Ask the OS for a free loopback port. The caller still uses --strictPort, so a race fails loudly. */\nexport function freePort() {\n    return new Promise((resolve, reject) => {\n        const srv = createServer();\n        srv.unref();\n        srv.on('error', reject);\n        srv.listen(0, '127.0.0.1', () => {\n            const addr = srv.address();\n            srv.close(() => (addr && typeof addr === 'object' ? resolve(addr.port) : reject(new Error('no port'))));\n        });\n    });\n}\n/**\n * The helper that serves static files and wraps script previews. It is plain\n * compiled CommonJS next to this module; from source (tests), the build output.\n */\nexport const PREVIEW_RUNNER = fileURLToPath(import.meta.url.endsWith('.ts')\n    ? new URL('../../lib/core/preview-runner.cjs', import.meta.url)\n    : new URL('./preview-runner.cjs', import.meta.url));\n/** A persisted Yarn wrapper must name this exact project and preview port. */\nexport function isPreviewProcess(preview, commandLine, windows = process.platform === 'win32') {\n    if (!commandHasMarkers(commandLine, [`--port ${preview.port}`], windows))\n        return false;\n    if (preview.kind === 'static' || preview.kind === 'script')\n        return commandHasMarkers(commandLine, [PREVIEW_RUNNER], windows);\n    if (preview.launcher !== 'yarn')\n        return commandHasMarkers(commandLine, [path.join(preview.cwd, 'node_modules', 'vite', 'bin', 'vite.js')], windows);\n    const cwd = [`--cwd ${preview.cwd}`, `--cwd \"${preview.cwd}\"`, `--cwd '${preview.cwd}'`];\n    return cwd.some(marker => commandHasMarkers(commandLine, [marker], windows)) && commandHasMarkers(commandLine, ['exec vite'], windows);\n}\nexport class PreviewError extends Error {\n    log;\n    constructor(message, log) {\n        super(message);\n        this.log = log;\n        this.name = 'PreviewError';\n    }\n}\nconst SUCCESS = (status) => status >= 200 && status < 300;\n/** Any answer short of a server error means a project server is up (it may redirect or have no root page). */\nconst ANSWERING = (status) => status >= 200 && status < 500;\nasync function httpReady(url, signal, accept = SUCCESS) {\n    try {\n        const res = await fetchPreview(url, { signal });\n        await res.body?.cancel();\n        return accept(res.status);\n    }\n    catch {\n        return false;\n    }\n}\n/**\n * Serve a copy on a dedicated loopback port and return only after it answers\n * HTTP. `build` serves the output of the build the checks just ran (`vite\n * preview`), so what the user tries is the artifact that passed; `dev` runs the\n * dev server and is used only when there is no build to serve. The Vite binary\n * runs on the host Node directly, except modern Yarn's project-aware loader;\n * its wrapper and the complete child tree share this preview's lifecycle.\n */\nexport async function startVitePreview(dir, opts = {}) {\n    const viteBin = path.join(dir, 'node_modules', 'vite', 'bin', 'vite.js');\n    const project = await inspectProject(dir);\n    const modernYarn = project.packageManager === 'yarn' && project.modernYarn === true;\n    if (!modernYarn && !existsSync(viteBin))\n        throw new PreviewError('副本里没有安装 vite', '');\n    const kind = opts.kind ?? 'build';\n    const timeoutMs = opts.timeoutMs ?? 60_000;\n    const host = `ac-${randomBytes(16).toString('hex')}.localhost`;\n    let lastError;\n   